window.Booking=(()=>{const $=id=>document.getElementById(id);const main=document.querySelector('main');document.querySelector('.intro').remove();const card=document.createElement('section');card.className='booking-card';card.innerHTML='<aside class="booking-info"><p class="eyebrow">SHIFT OUT OF LUCK</p><h1>A quick visit.<br>If you can fit it.</h1><p class="booking-note">Explore a possible visit · not a booking</p><div id="serviceFields"></div><div id="visitMeta"></div></aside><div class="booking-calendar"><h2>Select a day</h2><p class="micro">A typical week · New York time</p><div id="calendarDays"></div><div id="calendarMessage"></div><details class="schedule-edit" open><summary>Your availability</summary><div id="scheduleFields"></div></details></div><div class="booking-slots"><h2 id="slotTitle">Monday</h2><p class="micro">Sample starts within published hours</p><div id="slotList"></div><div id="slotDetail" aria-live="polite"></div></div>';main.prepend(card);
const choices=document.querySelector('.choices');$('serviceFields').append(choices.children[2]);$('scheduleFields').append(...choices.children);choices.remove();$('serviceFields').append($('office'));
$('calendarDays').append($('days'));document.querySelector('.day-head').remove();const compare=document.querySelector('.comparison'),detail=document.createElement('details');detail.className='timeline-detail';detail.innerHTML='<summary>See the timeline behind these slots</summary>';compare.before(detail);detail.append(compare);const assumption=document.querySelector('.assumptions');$('scheduleFields').append(assumption);$('booking')?.remove();let slots=[],current=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const time=n=>{n=(n%1440+1440)%1440;const h=Math.floor(n/60);return `${h%12||12}:${String(n%60).padStart(2,'0')} ${h<12?'am':'pm'}`;};
function render(r,s,day,p){current={r,s,day};$('slotTitle').textContent=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][day];$('visitMeta').innerHTML=`<p>◷ ${s.duration} minute visit${s.wait?' + '+s.wait+' minute wait':''}</p><p>↔ ${s.travel} minutes each way</p><p class="micro">${esc(r.address||r.borough)}</p>`;const busy=[['Work',p.work],['Commute',p.commute],['Care / life',p.life],['Sleep',p.sleep]];slots=[];for(const [a,b] of p.office)for(let t=Math.ceil(a/30)*30;t+s.duration+s.wait<=b;t+=30){const end=t+s.duration+s.wait;const reasons=busy.filter(([,xs])=>xs.some(([x,y])=>t-s.travel<y&&end+s.travel>x)).map(([label])=>label);const fits=p.windows.some(([x,y])=>t>=x&&end<=y);if(!fits&&!reasons.length)reasons.push('Travel / next-day commitment');slots.push({t,end,reasons,fits});}
if(p.first!==null&&!slots.some(x=>x.fits)){slots.push({t:p.first,end:p.first+s.duration+s.wait,reasons:[],fits:true});slots.sort((a,b)=>a.t-b.t);}
$('slotList').innerHTML=slots.length?slots.map((slot,i)=>`<button class="slot ${slot.fits?'fits':'clash'}" data-slot="${i}"><strong>${time(slot.t)}</strong><span>${slot.fits?'Fits your day':esc(slot.reasons.join(' + '))}</span></button>`).join(''):`<p class="empty-slots">${p.kind==='unknown'?'Hours aren’t verified.':p.office.length?'The visit is longer than the opening window.':'No regular hours on this day.'}</p>`;$('slotDetail').innerHTML='';$('calendarMessage').innerHTML=`<div class="calendar-verdict ${p.kind}">${p.kind==='fits'?'A possible window exists.':p.kind==='unknown'?'We need verified hours.':'Open hours. No usable window.'}</div><p class="micro">${p.kind==='fits'?'Select a time to inspect the trip. Actual appointments may differ.':'Try another day or change your availability. Tap a time to see the conflict.'}</p>`;
}
$('slotList').onclick=e=>{const b=e.target.closest('[data-slot]');if(!b)return;const slot=slots[+b.dataset.slot],{r,s}=current;$('slotList').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));$('slotDetail').innerHTML=`<strong>${slot.fits?'This could fit.':'This conflicts with '+esc(slot.reasons.join(' and ').toLowerCase())+'.'}</strong><p>Leave ${time(slot.t-s.travel)}<br>Visit ${time(slot.t)}–${time(slot.end)}<br>Return ${time(slot.end+s.travel)}</p>${slot.fits?`<a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Check actual appointments ↗</a>`:'<p class="micro">This is a schedule conflict, not proof that leave or another arrangement is unavailable.</p>'}`;};return {render};})();
